1	export function formatTitle(title, author) {
2	  return `${title.trim()} by ${author.trim()}`;
3	}
4	
5	export function slugify(text) {
6	  return text.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
7	}
8	
9	export function averageRating(ratings) {
10	  if (ratings.length === 0) return 0;
11	  return ratings.reduce((sum, r) => sum + r, 0) / ratings.length;
12	}
